[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('replay','compatibility','trial-plan','acceptance-report','story-lifecycle')]
    [string] $Operation,
    [Parameter(Mandatory = $true)]
    [string] $InputPath
)

$ErrorActionPreference = 'Stop'

function Read-Object { if (-not (Test-Path -LiteralPath $InputPath -PathType Leaf)) { throw 'Input file was not found.' }; try { $value=ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $InputPath) -AsHashtable -Depth 100 } catch { throw "Input is not valid JSON: $($_.Exception.Message)" }; if($value -isnot [System.Collections.IDictionary]){throw 'Input JSON must be an object.'};return $value }
function Need { param([System.Collections.IDictionary]$Object,[string]$Name);if(-not $Object.Contains($Name)-or $null -eq $Object[$Name]-or [string]::IsNullOrWhiteSpace([string]$Object[$Name])){throw "$Name is required."};return [string]$Object[$Name] }
function Read-Reference { param([System.Collections.IDictionary]$Reference,[string]$Name);$path=[IO.Path]::GetFullPath((Need $Reference 'path'));if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "$Name file was not found."};$sha=[Security.Cryptography.SHA256]::Create();$stream=[IO.File]::OpenRead($path);try{$hash=([Convert]::ToHexString($sha.ComputeHash($stream))).ToLowerInvariant()}finally{$stream.Dispose();$sha.Dispose()};if(-not $Reference.Contains('sha256')-or [string]$Reference.sha256.ToLowerInvariant() -cne $hash){throw "$Name hash does not match."};try{$value=ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $path) -AsHashtable -Depth 100}catch{throw "$Name JSON is invalid."};return $value }

function Expand-HelperValue {
    param([object]$Value, [string]$CaseRoot, [System.Collections.IDictionary]$PreviousCases)
    if ($Value -is [string]) {
        if ($Value -ceq '__CASE_ROOT__') { return $CaseRoot }
        if ($Value.StartsWith('__ACK_FROM_CASE:', [StringComparison]::Ordinal) -and $Value.EndsWith('__', [StringComparison]::Ordinal)) {
            $caseName = $Value.Substring(16, $Value.Length - 18); if (-not $PreviousCases.Contains($caseName)) { throw "Referenced helper case was not completed: $caseName." }
            return @($PreviousCases[$caseName].data.pending | ForEach-Object { [ordered]@{ eventId = [string]$_.eventId; outcome = 'applied' } })
        }
        if ($Value.StartsWith('__CASE:', [StringComparison]::Ordinal)) {
            $parts = $Value.Substring(7).Split(':'); $caseName = $parts[0]; if (-not $PreviousCases.Contains($caseName)) { throw "Referenced helper case was not completed: $caseName." }; $current = $PreviousCases[$caseName]
            foreach ($part in @($parts | Select-Object -Skip 1)) { if ($current -is [System.Collections.IDictionary]) { if (-not $current.Contains($part)) { throw "Referenced helper result field was not found: $Value." }; $current = $current[$part] } elseif ($current -is [System.Collections.IList]) { $current = $current[[int]$part] } else { throw "Referenced helper result path is not traversable: $Value." } }
            return $current
        }
        return $Value
    }
    if ($Value -is [System.Collections.IDictionary]) { $result = [ordered]@{}; foreach ($key in $Value.Keys) { $result[[string]$key] = Expand-HelperValue $Value[$key] $CaseRoot $PreviousCases }; return $result }
    if ($Value -is [System.Collections.IEnumerable]) { $items = @($Value | ForEach-Object { Expand-HelperValue $_ $CaseRoot $PreviousCases }); return ,$items }
    return $Value
}

function Invoke-HelperIntegration { param([System.Collections.IDictionary]$Scenario)
    if (-not $Scenario.Contains('helperIntegration') -or @($Scenario.helperIntegration).Count -eq 0) { return [ordered]@{verified=$false;cases=@()} }
    $root = Join-Path ([IO.Path]::GetTempPath()) ('TaigaMCP-acceptance-' + [Guid]::NewGuid().ToString('N')); [IO.Directory]::CreateDirectory($root) | Out-Null; $results=@(); $caseResults=@{}; $stateRoots=@{}
    try {
        foreach($case in @($Scenario.helperIntegration)) {
            if ($case -isnot [System.Collections.IDictionary]) { throw 'Each helperIntegration case must be an object.' }
            foreach($name in @('name','script','operation','input','expect')){Need $case $name|Out-Null}
            $caseRoot = $null
            if ($case.Contains('usesStateRoot') -and $case.usesStateRoot -eq $true) {
                $stateName = if ($case.Contains('stateName')) { [string]$case.stateName } else { [string]$case.name }
                if (-not $stateRoots.ContainsKey($stateName)) { $stateRoots[$stateName] = Join-Path $root ('state-' + $stateName); [IO.Directory]::CreateDirectory($stateRoots[$stateName]) | Out-Null }
                $caseRoot = $stateRoots[$stateName]
            }
            $inputValue = Expand-HelperValue $case.input $caseRoot $caseResults
            if ($case.Contains('setup') -and [string]$case.setup -ceq 'expired-dispatch') {
                $caseRoot = Join-Path $root ([string]$case.name); [IO.Directory]::CreateDirectory($caseRoot) | Out-Null
                $stateScript = Join-Path $PSScriptRoot 'workflow-state.ps1'; $packetScript = Join-Path $PSScriptRoot 'workflow-packet.ps1'; $syntheticPath = Join-Path $PSScriptRoot '..\assets\synthetic-run.json'; $init = ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $syntheticPath) -AsHashtable -Depth 100; $init.sessionId = 'acceptance-deadline-session'; $initPath = Join-Path $root 'deadline-init.json'; [IO.File]::WriteAllText($initPath,($init|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false)); $initLines=& pwsh -NoProfile -File $stateScript -Operation initialize-session -InputPath $initPath -StateRoot $caseRoot 2>&1; if($LASTEXITCODE -ne 0){throw 'Could not initialize the deadline helper workflow.'};$initResult=ConvertFrom-Json -InputObject ($initLines-join [Environment]::NewLine) -AsHashtable -Depth 100; $ticketKey='project:123:issue:99'; $claimPath=Join-Path $root 'deadline-claim.json'; [IO.File]::WriteAllText($claimPath,(@{sessionId=$init.sessionId;ownerGeneration=1;ticketKey=$ticketKey;repositoryIdentity='acceptance-repo';expectedRevision=$initResult.revision}|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$claimLines=& pwsh -NoProfile -File $stateScript -Operation claim-ticket -InputPath $claimPath -StateRoot $caseRoot 2>&1;if($LASTEXITCODE -ne 0){throw 'Could not claim the deadline helper ticket.'};$claimResult=ConvertFrom-Json -InputObject ($claimLines-join [Environment]::NewLine) -AsHashtable -Depth 100;$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$branch=(( & git -C $repo rev-parse --abbrev-ref HEAD).Trim());$head=(( & git -C $repo rev-parse HEAD).Trim());$contextPath=Join-Path $root 'deadline-context.txt';[IO.File]::WriteAllText($contextPath,'deadline helper context',[Text.UTF8Encoding]::new($false));$packetRequest=@{packetId='acceptance-deadline-packet';sessionId=$init.sessionId;runId='acceptance-deadline-run';ticket=@{ticketKey=$ticketKey;projectId=123;kind='issue';id=99;ref=99;title='Deadline helper'};contextPath=$contextPath;criteria=@(@{id='criterion-1';text='Block expired dispatch.'});repository=@{identity='acceptance-repo';repositoryPath=$repo;worktreePath=$repo;branch=$branch;baseSha=$head};requiredCommands=@('synthetic-check');unresolvedRequirements=@();authority=@{authorizedActions=@('dispatch');excludedActions=@()};deadline=@{startedAtUtc='2000-01-01T00:00:00Z';deadlineUtc='2000-01-01T00:01:00Z';elapsedBudgetMinutes=1};profiles=@{coordinator=@{model='gpt-6.1-sol';effort='high'};implementer=@{model='gpt-5.6-luna';effort='xhigh'};reviewer=@{model='gpt-6.1-sol';effort='high'}}};$packetPath=Join-Path $root 'deadline-packet-request.json';[IO.File]::WriteAllText($packetPath,($packetRequest|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$packetLines=& pwsh -NoProfile -File $packetScript -Operation create -InputPath $packetPath -StateRoot $caseRoot 2>&1;if($LASTEXITCODE -ne 0){throw 'Could not create the expired helper packet.'};$packetResult=ConvertFrom-Json -InputObject ($packetLines-join [Environment]::NewLine) -AsHashtable -Depth 100;$packetFile=[string]$packetResult.data.packetPath;$inputValue=@{sessionId=$init.sessionId;ownerGeneration=1;ticketKey=$ticketKey;actionId='deadline-action';workerId='worker-thread';packetReference=@{path=$packetFile;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $packetFile).Hash.ToLowerInvariant()}}
            }
            $inputPath=Join-Path $root (([IO.Path]::GetRandomFileName())+'.json');[IO.File]::WriteAllText($inputPath,($inputValue|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$scriptPath=Join-Path $PSScriptRoot ([string]$case.script);if(-not(Test-Path -LiteralPath $scriptPath -PathType Leaf)){throw "Helper script was not found: $($case.script)"};$args=@('-NoProfile','-File',$scriptPath,'-Operation',[string]$case.operation,'-InputPath',$inputPath);if($case.Contains('usesStateRoot') -and $case.usesStateRoot -eq $true){if($null -eq $caseRoot){$caseRoot=Join-Path $root ([string]$case.name)};$args+=@('-StateRoot',$caseRoot)};$lines=& pwsh @args 2>&1;$exit=$LASTEXITCODE;$raw=$lines-join [Environment]::NewLine;try{$actual=ConvertFrom-Json -InputObject $raw -AsHashtable -Depth 100}catch{throw "Helper integration returned invalid JSON for $($case.name): $raw"};$expectedOk=($case.expect.ok -eq $true);if(($exit -eq 0) -ne $expectedOk -or ($actual.ok -eq $true) -ne $expectedOk){$message=if($actual.Contains('error')){[string]$actual.error.message}else{$raw};throw "Helper integration case failed: $($case.name): $message"};foreach($field in @('decision','reason','stateMutation')){if($case.expect.Contains($field)-and [string]$actual.data[$field] -cne [string]$case.expect[$field]){throw "Helper integration case $($case.name) did not produce expected $field."}};$caseResults[[string]$case.name]=$actual;$results+=[ordered]@{name=[string]$case.name;operation=[string]$case.operation;ok=($actual.ok -eq $true);decision=if($actual.ok -eq $true){$actual.data.decision}else{$null};reason=if($actual.ok -eq $true){$actual.data.reason}else{$null}}
        }
        return [ordered]@{verified=$true;cases=$results}
    } finally { if(Test-Path -LiteralPath $root){Remove-Item -LiteralPath $root -Recurse -Force} }
}

function Invoke-Replay { param([System.Collections.IDictionary]$InputObject)
    $scenario=if($InputObject.Contains('scenarioReference')){Read-Reference $InputObject.scenarioReference 'scenario'}else{$InputObject};if([int]$scenario.schemaVersion -ne 1){throw 'Unsupported replay scenario version.'};foreach($name in @('runId','ticketKey','actions','events')){Need $scenario $name|Out-Null}
    $engineering=@($scenario.actions|Where-Object{$_.class -eq 'engineering' -and $_.actor -eq 'coordinator'});if($engineering.Count -gt 0){throw 'Replay contains coordinator engineering work.'}
    $workersByRole=@{};$workers=@();foreach($action in @($scenario.actions|Where-Object{$_.actor -in @('implementer','reviewer')})){if([string]::IsNullOrWhiteSpace([string]$action.workerId)){throw 'Engineering actions must identify their worker chat.'};$role=[string]$action.actor;if(-not $workersByRole.ContainsKey($role)){$workersByRole[$role]=[string]$action.workerId}elseif([string]$workersByRole[$role] -cne [string]$action.workerId){throw "Worker identity changed for $role during replay."};$workers+=[string]$action.workerId};$workers=@($workers|Select-Object -Unique)
    $events=@($scenario.events);$invalidEnums=@($events|Where-Object{$_.kind -eq 'finding' -and $_.disposition -notin @('open','fixed','rejected_accepted','escalated')});if($invalidEnums.Count -gt 0){throw 'Replay contains a noncanonical finding disposition.'};$missingRawExit=@($events|Where-Object{$_.kind -eq 'evidence' -and -not $_.Contains('rawExitCode')});if($missingRawExit.Count -gt 0){throw 'Replay evidence must retain the raw process exit code.'};$expiredDispatch=@($events|Where-Object{$_.kind -eq 'deadline' -and $_.dispatchAttempt -eq $true -and $_.allowed -eq $false});$invalidExpired=@($events|Where-Object{$_.kind -eq 'deadline' -and $_.dispatchAttempt -eq $true -and $_.expired -eq $true -and $_.allowed -ne $false});if($invalidExpired.Count -gt 0){throw 'Replay contains an expired dispatch that was allowed.'};$material=@($events|Where-Object{$_.kind -eq 'finding' -and ($_.severity -in @('high','critical') -or $_.material -eq $true) -and $_.disposition -eq 'open'});$publication=@($events|Where-Object{$_.kind -eq 'publication' -and ($_.accepted -eq $true -or $_.published -eq $true)});if($material.Count -gt 0 -and $publication.Count -gt 0){throw 'Replay published with unresolved material evidence.'};$waitMutations=@($events|Where-Object{$_.kind -eq 'wait' -and $_.mutatesState -eq $true}).Count;if($waitMutations -gt 0){throw 'Replay unchanged waits must not mutate state.'};$repairAttempts=@($events|Where-Object{$_.kind -eq 'receipt_repair'}).Count;if($repairAttempts -gt 2){throw 'Replay exceeds the bounded receipt repair limit.'};$copied=@($events|Where-Object{$_.kind -eq 'prompt' -and $_.fullReceiptCopied -eq $true}).Count;if($copied -gt 0){throw 'Replay cannot copy a complete receipt into a coordinator prompt.'};if(@($events|Where-Object{$_.kind -eq 'deadline'}).Count -eq 0){throw 'Replay must include deadline admission evidence.'};$helper=Invoke-HelperIntegration $scenario;return [ordered]@{offline=$true;nativeHostVerified=$false;accepted=$true;coordinatorEngineeringActions=$engineering.Count;workerIdsStable=$true;workerIds=$workers;publicationBlockedByMaterialEvidence=($material.Count -gt 0 -and $publication.Count -eq 0);repairAttempts=$repairAttempts;unchangedWaitMutations=$waitMutations;expiredDispatchesBlocked=$expiredDispatch.Count;rawExitEvidenceCount=$missingRawExit.Count -eq 0;enumValidation='canonical';helperIntegration=$helper}
}

function Invoke-Compatibility { param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('records')){throw 'records must be supplied.'};$accepted=@();foreach($record in @($InputObject.records)){if($record.schemaVersion -notin @(1,2)){throw "Unsupported record schema version: $($record.schemaVersion)."};if(-not $record.Contains('ticketKey')-or -not $record.Contains('phase')){throw 'Legacy/current record is missing ownership or phase.'};if(-not $record.Contains('receipt')-or $record.receipt -isnot [System.Collections.IDictionary]){throw 'Legacy/current record must carry its complete receipt object.'};if(-not $record.Contains('evidence')-or $record.evidence -is [string] -or $record.evidence -isnot [System.Collections.IEnumerable]){throw 'Legacy/current record must carry its complete evidence array.'};if(-not $record.receipt.Contains('recordId')-or [string]::IsNullOrWhiteSpace([string]$record.receipt.recordId)){throw 'Receipt round-trip identity is required.'};if($record.uncertainAction -eq $true -and $record.actionReconciled -eq $true){throw 'An uncertain action cannot be marked reconciled without external evidence.'};$receiptCopy=ConvertFrom-Json -InputObject ($record.receipt|ConvertTo-Json -Depth 100) -AsHashtable -Depth 100;$evidenceCopy=ConvertFrom-Json -InputObject (@($record.evidence)|ConvertTo-Json -Depth 100) -AsHashtable -Depth 100;$accepted+=[ordered]@{schemaVersion=[int]$record.schemaVersion;ticketKey=[string]$record.ticketKey;phase=[string]$record.phase;preservedReceipt=($receiptCopy.recordId -ceq $record.receipt.recordId);preservedEvidence=(@($evidenceCopy).Count -eq @($record.evidence).Count);receipt=$receiptCopy;evidence=@($evidenceCopy);ownerGeneration=$record.ownerGeneration}};return [ordered]@{compatible=$true;records=$accepted;rollback='unsupported_versions_fail_closed';actualRunMigrated=$false}
}

function Invoke-TrialPlan { param([System.Collections.IDictionary]$InputObject)
    foreach($name in @('ticketKey','repository','workerProfiles','authorization','stopConditions')){Need $InputObject $name|Out-Null};if($InputObject.workerProfiles.implementer.model -cne 'gpt-5.6-luna'-or $InputObject.workerProfiles.implementer.effort -cne 'xhigh'-or $InputObject.workerProfiles.reviewer.model -cne 'gpt-6.1-sol'-or $InputObject.workerProfiles.reviewer.effort -cne 'high'){throw 'Trial must name the exact worker profiles.'};if($InputObject.authorization.createChats -ne $true -or $InputObject.authorization.messageWorkers -ne $true){throw 'Trial authorization must explicitly cover ordinary chats and worker messages.'};return [ordered]@{ready=$true;nativeOperationsRequired=@('create_or_reuse_ordinary_chats','message_same_worker_chats','wait_threads','automation_update');ticketKey=[string]$InputObject.ticketKey;repository=[string]$InputObject.repository;workerProfiles=$InputObject.workerProfiles;automaticMerge=$false;publicationOnlyIfAuthorized=$true;stopConditions=@($InputObject.stopConditions);executes=$false}
}

function Invoke-Report { param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('offlineGates')){throw 'offlineGates must be supplied.'};$offline=@($InputObject.offlineGates);$offlinePassed=(@($offline|Where-Object{$_ -eq $true}).Count -eq $offline.Count -and $offline.Count -gt 0);$hostVerified=($InputObject.actualHostVerified -eq $true);$publicationVerified=($InputObject.publicationVerified -eq $true);return [ordered]@{offlineAccepted=$offlinePassed;actualHostVerified=$hostVerified;publicationVerified=$publicationVerified;overallOperationalAcceptance=($offlinePassed -and $hostVerified -and $publicationVerified);pendingGates=@(if(-not $hostVerified){'actual_host_trial'};if(-not $publicationVerified){'publication_exercise'});qualityEvidence=$InputObject.qualityEvidence;costEvidence=$InputObject.costEvidence;rawTokensAreNotAcceptanceGate=$true}
}

function Invoke-StoryLifecycle { param([System.Collections.IDictionary]$InputObject)
    foreach($name in @('schemaVersion','runId','ticketKey','parent','tasks','events','operations','restart')){Need $InputObject $name|Out-Null}
    if([int]$InputObject.schemaVersion -ne 1){throw 'Unsupported story lifecycle scenario version.'}
    $helperIntegration = Invoke-HelperIntegration $InputObject
    if($InputObject.Contains('helperIntegration') -and -not $helperIntegration.verified){throw 'Story lifecycle requires actual helper integration cases.'}
    $parent=$InputObject.parent;if($parent -isnot [System.Collections.IDictionary]){throw 'parent must be an object.'}
    if([string]$parent.kind -cne 'story'){throw 'Story lifecycle requires a story parent.'}
    foreach($name in @('id','projectId','completionPolicy','prState','done','selectedTaskIds','acceptedTaskIds')){if(-not $parent.Contains($name)){throw "parent.$name is required."}}
    $parentId=[long]$parent.id;$projectId=[long]$parent.projectId;$selected=@($parent.selectedTaskIds|ForEach-Object{[long]$_});$acceptedParent=@($parent.acceptedTaskIds|ForEach-Object{[long]$_})
    if(@($selected|Select-Object -Unique).Count -ne $selected.Count){throw 'The parent selectedTaskIds must not contain duplicates.'}
    $tasks=@($InputObject.tasks);$taskById=@{}
    foreach($task in $tasks){
        if($task -isnot [System.Collections.IDictionary]){throw 'Each lifecycle task must be an object.'}
        foreach($name in @('taskId','projectId','parentStoryId','ownedByStory','branch','childChat','childPr','events')){if(-not $task.Contains($name)){throw "task.$name is required."}}
        $id=[long]$task.taskId;if($id -lt 1 -or $taskById.ContainsKey([string]$id)){throw "Task identity is duplicated or invalid: $id."}
        if([long]$task.projectId -ne $projectId -or [long]$task.parentStoryId -ne $parentId -or $task.ownedByStory -ne $true){throw "Task $id is not owned by the selected story."}
        if(-not [string]::IsNullOrWhiteSpace([string]$task.branch) -or -not [string]::IsNullOrWhiteSpace([string]$task.childChat) -or -not [string]::IsNullOrWhiteSpace([string]$task.childPr)){throw "Task $id created an independent branch, chat, or PR."}
        $taskById[[string]$id]=$task
    }
    foreach($id in $selected){if(-not $taskById.ContainsKey([string]$id)){throw "Selected task evidence is missing: $id."}}
    foreach($id in $taskById.Keys){if($selected -notcontains [long]$id){throw "Unselected task was included in the story acceptance: $id."}}
    $events=@($InputObject.events)|Sort-Object {[long]$_.sequence};$seenEventIds=@{};$last=0L;$state=@{};$lastSha=@{};$criteriaByTask=if($InputObject.Contains('criteriaByTask')){$InputObject.criteriaByTask}else{$null};$statusMapping=if($InputObject.Contains('statusMapping')){$InputObject.statusMapping}else{$null}
    if($selected.Count -gt 0 -and ($criteriaByTask -isnot [System.Collections.IDictionary] -or $statusMapping -isnot [System.Collections.IDictionary])){throw 'Selected child lifecycle requires criteriaByTask and statusMapping bindings.'}
    if($selected.Count -gt 0){foreach($id in $selected){if(-not $criteriaByTask.Contains([string]$id)){throw "criteriaByTask is missing selected task $id."};if(@($criteriaByTask[[string]$id]).Count -eq 0){throw "criteriaByTask is empty for selected task $id."}}}
    foreach($event in $events){
        foreach($name in @('eventId','sequence','taskId','eventType','logicalState','statusId','currentSha','criterionIds','ticketKey','projectId','parentStoryId')){if(-not $event.Contains($name)){throw "event.$name is required."}}
        if($event.criterionIds -is [string] -or $event.criterionIds -isnot [System.Collections.IEnumerable] -or @($event.criterionIds).Count -eq 0){throw "event $($event.sequence) requires criterion evidence."}
        $sequence=[long]$event.sequence;if($sequence -ne ($last+1)){throw 'Lifecycle event sequences must be contiguous and restart-safe.'};$last=$sequence
        $eventId=[string]$event.eventId;if($seenEventIds.ContainsKey($eventId)){throw "Lifecycle event is duplicated: $eventId."};$seenEventIds[$eventId]=$true
        $taskId=[long]$event.taskId;if(-not $taskById.ContainsKey([string]$taskId)){throw "Lifecycle event references an unselected task: $taskId."}
        if([string]$event.ticketKey -cne [string]$InputObject.ticketKey -or [long]$event.projectId -ne $projectId -or [long]$event.parentStoryId -ne $parentId){throw "Task $taskId event is not bound to the lifecycle ticket/project/parent."}
        if([string]$event.currentSha -notmatch '^[0-9a-fA-F]{7,64}$'){throw "Task $taskId event currentSha is not a Git revision."}
        if($selected -notcontains $taskId){throw "Lifecycle event references a task outside the selected packet set: $taskId."}
        if($statusMapping -is [System.Collections.IDictionary]){if(-not $statusMapping.Contains($event.logicalState) -or [long]$statusMapping[$event.logicalState] -ne [long]$event.statusId){throw "Task $taskId event status does not match the trusted logical mapping."}}
        $expectedCriteria=@($criteriaByTask[[string]$taskId]|ForEach-Object{[string]$_}|Select-Object -Unique);$actualCriteria=@($event.criterionIds|ForEach-Object{[string]$_}|Select-Object -Unique);if((($expectedCriteria|Sort-Object)-join '|') -cne (($actualCriteria|Sort-Object)-join '|')){throw "Task $taskId event criteria are not bound to the selected packet (expected $($expectedCriteria -join ',') actual $($actualCriteria -join ','))."}
        $current=if($state.ContainsKey([string]$taskId)){[string]$state[[string]$taskId]}else{'not_started'}
        $next=[string]$event.logicalState
        $allowed=@{not_started=@('in_progress');in_progress=@('awaiting_review','blocked','in_progress');blocked=@('in_progress');awaiting_review=@('accepted','in_progress');accepted=@('in_progress','accepted')}
        if(-not $allowed.ContainsKey($current)-or $allowed[$current] -notcontains $next){throw "Invalid task $taskId lifecycle transition $current -> $next."}
        if($next -eq 'accepted' -and ([string]$event.eventType -cne 'accepted' -or -not $event.Contains('reviewAccepted') -or $event.reviewAccepted -ne $true -or -not $event.Contains('reviewedSha') -or [string]::IsNullOrWhiteSpace([string]$event.reviewedSha))){throw "Task $taskId Done requires an individual reviewer acceptance event."}
        if($next -eq 'accepted' -and [string]$event.reviewedSha -cne [string]$event.currentSha){throw "Task $taskId reviewer evidence is stale."}
        if($event.Contains('reviewedSha') -and [string]$event.reviewedSha -cne [string]$event.currentSha){throw "Task $taskId carries stale reviewed SHA evidence."}
        $state[[string]$taskId]=$next;$lastSha[[string]$taskId]=[string]$event.currentSha
    }
    $restart=$InputObject.restart;if($restart -isnot [System.Collections.IDictionary]){throw 'restart must be an object.'}
    foreach($name in @('atSequence','persistedCursor','resumeCursor')){if(-not $restart.Contains($name)){throw "restart.$name is required."}}
    if([long]$restart.persistedCursor -ne [long]$restart.atSequence -or [long]$restart.resumeCursor -ne [long]$restart.atSequence -or $restart.Contains('omittedCursor') -and $restart.omittedCursor -ne $true){throw 'Restart must resume from the persisted progress cursor without replaying old transitions.'}
    $writes=@($InputObject.operations|Where-Object{$_.kind -eq 'taiga_task_write'});$workerWrites=@($InputObject.operations|Where-Object{$_.actor -in @('implementer','reviewer') -and $_.kind -eq 'taiga_task_write'});if($workerWrites.Count -gt 0){throw 'Only the coordinator may write Taiga task status.'}
    foreach($write in $writes){if([string]$write.actor -cne 'coordinator'){throw 'Task status write is not coordinator-owned.'};if($selected -notcontains [long]$write.taskId){throw "Task write is outside the selected story scope: $($write.taskId)."};if([string]$write.outcome -notin @('applied','unchanged','reconciled')){throw "Task write $($write.taskId) lacks a reconciled outcome."}}
    foreach($id in $selected){if($state[[string]$id] -ne 'accepted' -or $acceptedParent -notcontains $id){throw "Parent completion is hiding missing accepted evidence for task $id."}}
    if($selected.Count -gt 0){
        if(-not $InputObject.Contains('taskAcceptances') -or @($InputObject.taskAcceptances).Count -ne $selected.Count){throw 'Final lifecycle evidence requires one reviewer taskAcceptance per selected task.'}
        foreach($id in $selected){$acceptance=@($InputObject.taskAcceptances|Where-Object{[long]$_.taskId -eq $id});if($acceptance.Count -ne 1 -or $acceptance[0].accepted -ne $true -or [string]$acceptance[0].reviewedSha -cne $lastSha[[string]$id]){throw "Task $id lacks a final revision-bound reviewer acceptance."};$expected=@($criteriaByTask[[string]$id]|ForEach-Object{[string]$_}|Sort-Object);$actual=@($acceptance[0].criterionIds|ForEach-Object{[string]$_}|Sort-Object);if(($expected -join '|') -cne ($actual -join '|')){throw "Task $id reviewer acceptance criteria are incomplete or unrelated."}}
    }
    if([string]$parent.prState -cne 'merged' -or $parent.done -ne $true -or [string]$parent.completionPolicy -ne 'merged'){throw 'Parent story completion does not satisfy its existing merged policy.'}
    return [ordered]@{offline=$true;accepted=$true;runId=[string]$InputObject.runId;ticketKey=[string]$InputObject.ticketKey;selectedTaskIds=$selected;finalTaskStates=$state;eventCount=$events.Count;restartRecovered=$true;coordinatorOnlyWrites=$true;independentChildBranches=0;independentChildChats=0;independentChildPrs=0;parentCompletionPolicy=[string]$parent.completionPolicy;helperIntegration=$helperIntegration;realHostVerified=$false}
}

try{$inputObject=Read-Object;$data=switch($Operation){'replay'{Invoke-Replay $inputObject};'compatibility'{Invoke-Compatibility $inputObject};'trial-plan'{Invoke-TrialPlan $inputObject};'acceptance-report'{Invoke-Report $inputObject};'story-lifecycle'{Invoke-StoryLifecycle $inputObject}};[ordered]@{ok=$true;operation=$Operation;data=$data}|ConvertTo-Json -Depth 100;exit 0}catch{[ordered]@{ok=$false;operation=$Operation;error=[ordered]@{category='workflow_acceptance';message=$_.Exception.Message}}|ConvertTo-Json -Depth 20;exit 1}
